import { debugGetAllActionTemplates, getCurrentState } from "./game/mainSimulationLogic";
import { isChoiceTemplate } from "./UIfacade/actionFacade";
  const activablesState = getCurrentState().getInternalStateObject().activables;
  let result = 'ACTION TEMPLATES';
  debugGetAllActionTemplates()
    .forEach(actTemplate => {
      result += '<br/><br/>' + JSON.stringify(actTemplate) + '<br/>' + JSON.stringify(activablesState[actTemplate.uid]);

      if (isChoiceTemplate(actTemplate)) {
        actTemplate.choices.forEach(choice => result += '<br/>' + JSON.stringify(activablesState[choice.uid]))
      }
    });
  result;
